import fs from "node:fs";
import { execFileSync } from "node:child_process";

const sha = process.env.GITHUB_SHA || execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim();
const runId = process.env.GITHUB_RUN_ID || "local";
const repository = process.env.GITHUB_REPOSITORY || "Akshayshetye37/Aurelia-apk";
const server = process.env.GITHUB_SERVER_URL || "https://github.com";
const workflowName = process.env.GITHUB_WORKFLOW || "local verification";

const body = `# Aurelia R1 status

**Release:** R1 — local-only PMS  
**Status:** **NOT RELEASE READY**  
**Generated by:** ${workflowName}  
**Candidate SHA:** \`${sha}\`  
**Workflow run:** ${runId === "local" ? "local (not CI evidence)" : `[${runId}](${server}/${repository}/actions/runs/${runId})`}

## Required check scope

The R1 required check runs on every push and pull request, checks out \`${sha}\` explicitly, verifies the checkout SHA, tests release defaults, runs the complete PMS test suite, builds the production web bundle and scans production assets.

A successful R1 workflow does **not** qualify Android hardware, financial data migration, accounting sign-off, physical devices, signing, backup/restore, or production operations.

## Workstream status

| Workstream | Status | Acceptance still required |
|---|---|---|
| 0. Governance | PARTIAL / ADMIN BLOCKED | Protect \`main\` and \`release/r1-local-first-execution\`; require one review, exact R1 status check, no force-push and admin enforcement. |
| 1. Local-first data | PARTIAL | Complete repository-only read/write cutover domain-by-domain, shadow comparison, zero mismatches, legacy quarantine, IndexedDB/SQLite contract suite and rollback drills. |
| 2. Financial correctness | BLOCKED | Run read-only diagnostic on authorized redacted backup; accounting-owner written sign-off; implement append-only integer-paise journal, atomic payment/journal/outbox and idempotency tests. |
| 3. Atomic operations | PARTIAL | Complete five required commands as single DB transactions and inject failure at every write step; verify folio/ledger and stock/movement invariants. |
| 4. Android/security | BLOCKED | Complete DEK envelope design/tests, Kotlin compile/unit tests, instrumentation, storage-full/rollback/migration/process-kill tests and two-phone qualification. |
| 5. R1 operations/release | BLOCKED | Offline lifecycle regression, restart reconciliation, owner-controlled signing, exact tagged-SHA build, permissions/flags review and upgrade test. |
| 6. R2/R3 | DEFERRED | Provider sandbox/webhook/refund qualification and sync stay out of R1. |

## Fail-closed release profile

- \`uiCutover=false\`; sync OFF; gateway entry points OFF; Pay Bridge OFF.
- CCAvenue OFF; enabled provider list empty.
- Automatic settlement and refund posting OFF.
- R1 release publishing NOT AUTHORIZED.

## Evidence required outside CI

- Redacted backup and accounting owner's written sign-off.
- Two physical Android phones (one low-end).
- Owner-controlled signing key.
- Repository owner/admin action to apply branch protection/rulesets.

**Completion rule:** no item is DONE on documentation alone. Each gate requires implementation, regression coverage, passing CI on this exact SHA and required external evidence.
`;

fs.writeFileSync("STATUS.md", body);
console.log("Generated STATUS.md for " + sha + " (" + runId + ").");
